customCss:
.wb-addon-marquee{padding:40px 0;width:100%;overflow:hidden;font-family:inherit;display:flex;flex-direction:column;align-items:center}
.wb-mq-header{text-align:center;margin-bottom:16px;padding:0 20px;position:relative;z-index:2}
.wb-mq-title{font-size:1.8rem;font-weight:800;color:var(--text-main,#f8fafc);margin:0;letter-spacing:-.02em}
.wb-mq-status{display:inline-flex;align-items:center;gap:6px;font-size:0.75rem;padding:3px 12px;border-radius:12px;background:rgba(99,102,241,0.12);color:#a5b4fc;border:1px solid rgba(99,102,241,0.25)}
.wb-mq-wrapper{width:100%;overflow:hidden;position:relative;display:flex;mask-image:linear-gradient(to right,transparent,black 10%,black 90%,transparent);-webkit-mask-image:linear-gradient(to right,transparent,black 10%,black 90%,transparent);padding:58px 0 28px;}
.wb-mq-track{display:flex;gap:var(--mq-gap,24px);width:max-content;animation:mq-scroll-left var(--mq-speed,40s) linear infinite;will-change:transform;}

/* Right Direction */
.wb-addon-marquee[data-direction="right"] .wb-mq-track{animation-name:mq-scroll-right}

/* Pause on Hover */
.wb-mq-wrapper:hover .wb-mq-track{animation-play-state:paused}

/* Item Styles */
.wb-mq-item{display:block;position:relative;text-decoration:none !important;flex-shrink:0;transition:transform .3s ease}
.wb-mq-item:hover{transform:translateY(-4px);z-index:50;}
.wb-mq-img-wrap{height:var(--mq-height,120px);aspect-ratio:16/10;border-radius:12px;overflow:hidden;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);transition:border-color .3s ease,box-shadow .3s ease}
.wb-mq-item:hover .wb-mq-img-wrap{border-color:var(--mq-accent,#6366f1);box-shadow:0 10px 20px -10px var(--mq-accent)}
.wb-mq-img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .4s ease}
.wb-mq-item:hover .wb-mq-img{transform:scale(1.08)}

/* TOOLTIP STYLES (Fixed Headroom & Clean Visibility) */
.wb-mq-tooltip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%) translateY(8px);background:var(--mq-accent,#6366f1);color:#fff !important;text-decoration:none !important;line-height:1.3;font-size:.8rem;font-weight:700;padding:6px 14px;border-radius:8px;white-space:nowrap;opacity:0;visibility:hidden;transition:opacity .22s ease,transform .22s ease,visibility .22s;pointer-events:none;z-index:100;box-shadow:0 6px 20px rgba(0,0,0,.45);will-change:transform,opacity;}
.wb-mq-tooltip::after{content:'';position:absolute;top:100%;left:50%;transform:translateX(-50%);border:6px solid transparent;border-top-color:var(--mq-accent,#6366f1)}
.wb-mq-item:hover .wb-mq-tooltip{opacity:1;visibility:visible;transform:translateX(-50%) translateY(0)}

/* Keyframes */
@keyframes mq-scroll-left{from{transform:translateX(0)}to{transform:translateX(calc(-50% - var(--mq-gap,24px) / 2))}}
@keyframes mq-scroll-right{from{transform:translateX(calc(-50% - var(--mq-gap,24px) / 2))}to{transform:translateX(0)}}

@media(max-width:600px){
  .wb-addon-marquee{padding:30px 0}
  .wb-mq-title{font-size:1.5rem}
  .wb-mq-wrapper{padding:50px 0 20px}
  .wb-mq-img-wrap{height:calc(var(--mq-height,120px) * 0.8)}
}

@media(prefers-reduced-motion:reduce){
  .wb-mq-track{animation:none !important;flex-wrap:wrap;justify-content:center}
  .wb-mq-wrapper{overflow:visible;mask-image:none;-webkit-mask-image:none}
}

customJs:
function onMount(el, props) {
  var root = el.querySelector('.wb-addon-marquee');
  var track = el.querySelector('[data-mq-track]');
  var statusEl = el.querySelector('.wb-mq-status');
  if (!root || !track) return;

  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
  var showTooltip = props.showTooltip !== false && props.showTooltip !== 'false';
  var dataSource = props.dataSource || 'manual';

  function setStatus(badgeHtml) {
    if (!statusEl) return;
    if (badgeHtml) {
      statusEl.innerHTML = badgeHtml;
      statusEl.style.display = 'inline-flex';
    } else {
      statusEl.style.display = 'none';
    }
  }

  function renderItems(itemsList) {
    var validItems = Array.isArray(itemsList) ? itemsList.filter(function(i){ return i && i.imageUrl; }) : [];
    if (!validItems.length) {
      track.innerHTML = '<div style="color:#94a3b8;padding:24px;font-size:0.9rem;">Add images in the Inspector, or connect a Google Sheet / SQL source.</div>';
      return;
    }

    var html = validItems.map(function(item) {
      var img = item.imageUrl 
        ? '<img src="' + esc(item.imageUrl) + '" class="wb-mq-img" loading="lazy" alt="' + esc(item.tooltipText || '') + '">' 
        : '<div class="wb-mq-img" style="background:#1e293b;"></div>';

      var tooltip = '';
      if (showTooltip && item.tooltipText) {
        tooltip = '<div class="wb-mq-tooltip">' + esc(item.tooltipText) + '</div>';
      }

      var innerHtml = tooltip + '<div class="wb-mq-img-wrap">' + img + '</div>';

      if (item.link) {
        return '<a href="' + esc(item.link) + '" class="wb-mq-item">' + innerHtml + '</a>';
      } else {
        return '<div class="wb-mq-item">' + innerHtml + '</div>';
      }
    }).join('');

    // Seamless duplication (ensures marquee loop never cuts abruptly)
    var repeatCount = validItems.length < 5 ? 4 : (validItems.length < 10 ? 3 : 2);
    var fullHtml = '';
    for (var r = 0; r < repeatCount; r++) { fullHtml += html; }
    track.innerHTML = fullHtml;
  }

  // 1. Google Sheets CSV Support
  function normalizeSheetUrl(url) {
    if (!url) return '';
    var clean = String(url).trim();
    if (clean.indexOf('/pub?output=csv') !== -1 || clean.indexOf('/export?format=csv') !== -1) return clean;
    if (clean.indexOf('/pubhtml') !== -1) return clean.replace('/pubhtml', '/pub?output=csv');
    if (clean.indexOf('/pub?') !== -1 && clean.indexOf('output=csv') === -1) return clean + '&output=csv';
    var m = clean.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
    if (m && m[1]) {
      var gidMatch = clean.match(/[#&?]gid=([0-9]+)/);
      var gid = (gidMatch && gidMatch[1]) ? gidMatch[1] : '0';
      return 'https://docs.google.com/spreadsheets/d/' + m[1] + '/export?format=csv&gid=' + gid;
    }
    return clean;
  }

  function parseCsv(text) {
    var lines = text.split(/\r?\n/).filter(function(l) { return l.trim().length > 0; });
    if (!lines.length) return [];
    var parseLine = function(line) {
      var row = [], curr = '', inQ = false;
      for (var i = 0; i < line.length; i++) {
        var c = line[i];
        if (c === '"') { inQ = !inQ; }
        else if (c === ',' && !inQ) { row.push(curr.trim()); curr = ''; }
        else { curr += c; }
      }
      row.push(curr.trim());
      return row;
    };
    var headers = parseLine(lines[0]).map(function(h) { return h.toLowerCase().replace(/[^a-z0-9]/g, ''); });
    var results = [];
    for (var j = 1; j < lines.length; j++) {
      var cells = parseLine(lines[j]);
      var obj = {};
      for (var k = 0; k < headers.length; k++) {
        obj[headers[k]] = cells[k] || '';
      }
      results.push(obj);
    }
    return results;
  }

  function syncGoogleSheet() {
    var rawUrl = props.googleSheetUrl;
    if (!rawUrl) {
      renderItems(props.items);
      return;
    }
    var sheetUrl = normalizeSheetUrl(rawUrl);
    setStatus('<span>⏳</span> Syncing Google Sheet...');
    fetch(sheetUrl, { credentials: 'omit' })
      .then(function(res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.text();
      })
      .then(function(csvText) {
        if (!csvText || csvText.indexOf('<!DOCTYPE') === 0) throw new Error('Sheet is private or invalid CSV');
        var rows = parseCsv(csvText);
        var parsedItems = rows.map(function(row) {
          var img = row.imageurl || row.image || row.img || row.photo || row.logo || row.picture || row.url || '';
          var tip = row.tooltiptext || row.tooltip || row.title || row.name || row.caption || row.label || row.project || '';
          var link = row.link || row.href || row.website || row.page || '';
          return { imageUrl: img, tooltipText: tip, link: link };
        }).filter(function(it) { return it.imageUrl; });

        if (parsedItems.length) {
          renderItems(parsedItems);
          setStatus('<span>✓</span> Google Sheet Live (' + parsedItems.length + ' items)');
        } else {
          throw new Error('No image URLs found in sheet columns');
        }
      })
      .catch(function(err) {
        console.warn('[Marquee] Google Sheet sync notice:', err.message);
        setStatus('<span>⚠️</span> Sheet fallback to manual');
        renderItems(props.items);
      });
  }

  // 2. SQL / REST API Connection Support
  function syncSqlApi() {
    var endpoint = props.sqlEndpointUrl || 'api.php?action=get_marquee_images';
    if (props.sqlQueryTable && endpoint.indexOf('api.php') !== -1 && endpoint.indexOf('table=') === -1) {
      endpoint += (endpoint.indexOf('?') === -1 ? '?' : '&') + 'table=' + encodeURIComponent(props.sqlQueryTable);
    }
    setStatus('<span>⏳</span> Querying SQL Database...');
    fetch(endpoint)
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var itemsArr = Array.isArray(data) ? data : (data && Array.isArray(data.items) ? data.items : (data && Array.isArray(data.images) ? data.images : []));
        var mapped = itemsArr.map(function(r) {
          return {
            imageUrl: r.imageUrl || r.image_url || r.img || r.image || r.url || '',
            tooltipText: r.tooltipText || r.tooltip_text || r.title || r.name || r.caption || '',
            link: r.link || r.href || r.url || ''
          };
        }).filter(function(it) { return it.imageUrl; });

        if (mapped.length) {
          renderItems(mapped);
          setStatus('<span>✓</span> Database Live (' + mapped.length + ' items)');
        } else {
          throw new Error('No items returned');
        }
      })
      .catch(function(err) {
        console.warn('[Marquee] SQL API sync notice:', err.message);
        setStatus('<span>⚠️</span> SQL fallback to manual');
        renderItems(props.items);
      });
  }

  // Route by configured Data Source
  if (dataSource === 'google_sheets' && props.googleSheetUrl) {
    syncGoogleSheet();
  } else if (dataSource === 'sql_api') {
    syncSqlApi();
  } else {
    setStatus('');
    renderItems(props.items);
  }

  el.__wbDestroy = function () {};
}
